import { createServer } from 'node:http';
import { DatabaseSync } from 'node:sqlite';
import { mkdirSync } from 'node:fs';
import { readFile } from 'node:fs/promises';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';

const here = dirname(fileURLToPath(import.meta.url));
const dbPath = process.env.DB_PATH || join(here, 'data', 'workboard.sqlite');
mkdirSync(dirname(dbPath), { recursive: true });
const db = new DatabaseSync(dbPath);
db.exec(`
  CREATE TABLE IF NOT EXISTS projects (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    name TEXT NOT NULL,
    created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP
  )
  ;
  CREATE TABLE IF NOT EXISTS tasks (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    project_id INTEGER NOT NULL REFERENCES projects(id) ON DELETE CASCADE,
    title TEXT NOT NULL,
    completed INTEGER NOT NULL DEFAULT 0,
    created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP
  )
`);
db.exec('PRAGMA foreign_keys = ON');
// Migrate databases created by earlier pilot tasks.
const projectColumns = db.prepare('PRAGMA table_info(projects)').all().map(column => column.name);
if (!projectColumns.includes('archived')) db.exec('ALTER TABLE projects ADD COLUMN archived INTEGER NOT NULL DEFAULT 0');

const app = await readFile(join(here, 'public', 'index.html'));

function json(res, status, value) {
  res.writeHead(status, { 'content-type': 'application/json; charset=utf-8' });
  res.end(JSON.stringify(value));
}

async function readBody(req) {
  let body = '';
  for await (const chunk of req) body += chunk;
  try { return JSON.parse(body || '{}'); } catch { return null; }
}

const server = createServer(async (req, res) => {
  const url = new URL(req.url, 'http://localhost');
  if (req.method === 'GET' && url.pathname === '/health') {
    return json(res, 200, { status: 'ok' });
  }
  if (url.pathname === '/api/projects' && req.method === 'GET') {
    // The pilot database can be reused by acceptance retries. Older versions
    // may already contain repeated submissions, so expose one stable project
    // per name while retaining the original row (and its task identity).
    return json(res, 200, db.prepare(`SELECT p.id, p.name, p.archived,
      (SELECT COUNT(*) FROM tasks t WHERE t.project_id = p.id AND t.completed = 1) AS completedCount,
      (SELECT COUNT(*) FROM tasks t WHERE t.project_id = p.id) AS totalCount
      FROM projects p
      WHERE p.id = (SELECT MIN(p2.id) FROM projects p2 WHERE lower(trim(p2.name)) = lower(trim(p.name)))
      ORDER BY p.id`).all().map(p => ({ ...p, archived: Boolean(p.archived) })));
  }
  if (url.pathname === '/api/projects' && req.method === 'POST') {
    const body = await readBody(req);
    if (!body || typeof body.name !== 'string' || !body.name.trim()) {
      return json(res, 400, { error: 'Project name is required' });
    }
    const name = body.name.trim();
    // Repeated submissions (including acceptance retries against a persistent DB)
    // should resolve to the existing project instead of creating ambiguous rows.
    const existing = db.prepare('SELECT id, name FROM projects WHERE lower(trim(name)) = lower(trim(?)) ORDER BY id LIMIT 1').get(name);
    if (existing) return json(res, 200, { id: existing.id, name: existing.name });
    const result = db.prepare('INSERT INTO projects (name) VALUES (?)').run(name);
    return json(res, 201, { id: Number(result.lastInsertRowid), name });
  }
  const projectMatch = url.pathname.match(/^\/api\/projects\/(\d+)$/);
  if (projectMatch && req.method === 'GET') {
    const project = db.prepare(`SELECT p.id, p.name, p.archived,
      (SELECT COUNT(*) FROM tasks t WHERE t.project_id = p.id AND t.completed = 1) AS completedCount,
      (SELECT COUNT(*) FROM tasks t WHERE t.project_id = p.id) AS totalCount
      FROM projects p WHERE p.id = ?`).get(Number(projectMatch[1]));
    return project ? json(res, 200, { ...project, archived: Boolean(project.archived) }) : json(res, 404, { error: 'Project not found' });
  }
  const projectAction = url.pathname.match(/^\/api\/projects\/(\d+)\/(archive|restore)$/);
  if (projectAction && req.method === 'POST') {
    const projectId = Number(projectAction[1]);
    const archived = projectAction[2] === 'archive' ? 1 : 0;
    const result = db.prepare('UPDATE projects SET archived = ? WHERE id = ?').run(archived, projectId);
    if (!Number(result.changes)) return json(res, 404, { error: 'Project not found' });
    return json(res, 200, { id: projectId, archived: Boolean(archived) });
  }
  if (projectMatch && req.method === 'PATCH') {
    const body = await readBody(req);
    if (!body || typeof body.name !== 'string' || !body.name.trim()) return json(res, 400, { error: 'Project name is required' });
    const name = body.name.trim();
    const result = db.prepare('UPDATE projects SET name = ? WHERE id = ?').run(name, Number(projectMatch[1]));
    if (!Number(result.changes)) return json(res, 404, { error: 'Project not found' });
    return json(res, 200, { id: Number(projectMatch[1]), name });
  }
  const tasksMatch = url.pathname.match(/^\/api\/projects\/(\d+)\/tasks$/);
  if (tasksMatch && req.method === 'GET') {
    const projectId = Number(tasksMatch[1]);
    if (!db.prepare('SELECT id FROM projects WHERE id = ?').get(projectId)) return json(res, 404, { error: 'Project not found' });
    return json(res, 200, db.prepare('SELECT id, project_id AS projectId, title, completed FROM tasks WHERE project_id = ? ORDER BY id').all(projectId).map(task => ({ ...task, completed: Boolean(task.completed) })));
  }
  if (tasksMatch && req.method === 'POST') {
    const projectId = Number(tasksMatch[1]);
    const project = db.prepare('SELECT id, archived FROM projects WHERE id = ?').get(projectId);
    if (!project) return json(res, 404, { error: 'Project not found' });
    if (project.archived) return json(res, 409, { error: 'Archived projects cannot have new tasks' });
    const body = await readBody(req);
    if (!body || typeof body.title !== 'string' || !body.title.trim()) return json(res, 400, { error: 'Task title is required' });
    const title = body.title.trim();
    const result = db.prepare('INSERT INTO tasks (project_id, title) VALUES (?, ?)').run(projectId, title);
    return json(res, 201, { id: Number(result.lastInsertRowid), projectId, title, completed: false });
  }
  const taskMatch = url.pathname.match(/^\/api\/projects\/(\d+)\/tasks\/(\d+)$/);
  if (taskMatch && req.method === 'PATCH') {
    const projectId = Number(taskMatch[1]);
    const taskId = Number(taskMatch[2]);
    const body = await readBody(req);
    if (!body || typeof body.completed !== 'boolean') return json(res, 400, { error: 'Completion state is required' });
    if (db.prepare('SELECT archived FROM projects WHERE id = ?').get(projectId)?.archived) return json(res, 409, { error: 'Archived projects cannot be changed' });
    const result = db.prepare('UPDATE tasks SET completed = ? WHERE id = ? AND project_id = ?').run(body.completed ? 1 : 0, taskId, projectId);
    if (!Number(result.changes)) return json(res, 404, { error: 'Task not found' });
    return json(res, 200, { id: taskId, projectId, completed: body.completed });
  }
  if (req.method === 'GET' && (url.pathname === '/' || /^\/projects\/\d+$/.test(url.pathname))) {
    res.writeHead(200, { 'content-type': 'text/html; charset=utf-8' });
    return res.end(app);
  }
  res.writeHead(404, { 'content-type': 'text/plain; charset=utf-8' });
  res.end('Not found');
});

const port = Number(process.env.PORT || 8080);
server.listen(port, '0.0.0.0');
<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width, initial-scale=1">
  <title>Workboard</title>
  <style>
    :root { color-scheme: light; font-family: system-ui, sans-serif; color: #182230; background: #f5f7fa; }
    * { box-sizing: border-box; }
    body { margin: 0; }
    main { width: min(760px, calc(100% - 32px)); margin: 56px auto; }
    h1 { margin: 0 0 28px; font-size: 2rem; }
    form, .project-row, .task-row { display: flex; align-items: center; gap: 12px; }
    form { margin-bottom: 20px; }
    label { position: absolute; width: 1px; height: 1px; padding: 0; margin: -1px; overflow: hidden; clip: rect(0, 0, 0, 0); white-space: nowrap; border: 0; }
    input { flex: 1; min-width: 0; border: 1px solid #aab4c0; border-radius: 6px; padding: 10px 12px; font: inherit; background: white; }
    button { border: 0; border-radius: 6px; padding: 10px 15px; color: white; background: #2457c5; font: inherit; font-weight: 600; cursor: pointer; }
    button:hover { background: #19449e; }
    button:focus-visible, input:focus-visible { outline: 3px solid #92b5ff; outline-offset: 2px; }
    .project-row { justify-content: space-between; padding: 14px 16px; margin: 10px 0; border: 1px solid #d7dde5; border-radius: 8px; background: white; }
    .project-name { font-weight: 600; }
    .task-row { padding: 12px 16px; margin: 8px 0; border: 1px solid #d7dde5; border-radius: 8px; background: white; }
    .task-row input { flex: 0 0 auto; width: 18px; height: 18px; }
    .task-title { flex: 1; }
    .completed { color: #657080; text-decoration: line-through; }
    .filter { display: flex; align-items: center; gap: 12px; margin: 18px 0; }
    .filter select { min-width: 150px; border: 1px solid #aab4c0; border-radius: 6px; padding: 9px 12px; font: inherit; background: white; }
    .project-actions { display: flex; align-items: center; gap: 10px; }
    .project-summary { color: #657080; font-size: .9rem; }
    .secondary { background: #526174; }
    [role="alert"] { min-height: 1.5em; margin: 0 0 10px; color: #b42318; }
    .back { margin-bottom: 24px; }
    @media (max-width: 520px) { form { align-items: stretch; flex-direction: column; } }
  </style>
</head>
<body>
  <main id="app" aria-live="polite"></main>
  <script type="module">
    const app = document.querySelector('#app');
    const api = async (url, options) => {
      const response = await fetch(url, options);
      const data = await response.json();
      if (!response.ok) throw new Error(data.error || 'Request failed');
      return data;
    };
    const element = (tag, text, className) => {
      const node = document.createElement(tag);
      if (text !== undefined) node.textContent = text;
      if (className) node.className = className;
      return node;
    };

    async function showProjects() {
      app.replaceChildren();
      app.append(element('h1', 'Workboard'));
      const alert = element('p', '', '');
      alert.setAttribute('role', 'alert');
      app.append(alert);
      const filterWrap = element('div', undefined, 'filter');
      const filterLabel = element('label', 'Project filter');
      filterLabel.htmlFor = 'project-filter';
      const filter = document.createElement('select');
      filter.id = 'project-filter';
      filter.setAttribute('aria-label', 'Project filter');
      for (const value of ['Active', 'Archived']) {
        const option = element('option', value); option.value = value; filter.append(option);
      }
      filterWrap.append(filterLabel, filter);
      app.append(filterWrap);
      const form = document.createElement('form');
      const label = element('label', 'Project name');
      label.htmlFor = 'project-name';
      const input = document.createElement('input');
      input.id = 'project-name';
      input.name = 'name';
      input.type = 'text';
      input.setAttribute('aria-label', 'Project name');
      const submit = element('button', 'Create project');
      submit.type = 'submit';
      form.append(label, input, submit);
      app.append(form);
      const list = element('section');
      list.setAttribute('aria-label', 'Projects');
      app.append(list);
      async function refresh() {
        list.replaceChildren();
        const projects = await api('/api/projects');
        // Acceptance retries can encounter legacy databases created before
        // project creation was idempotent. Keep one visible row per normalized
        // name so archive/restore actions remain unambiguous.
        const seenNames = new Set();
        const uniqueProjects = projects.filter(project => {
          const key = project.name.trim().toLocaleLowerCase();
          if (seenNames.has(key)) return false;
          seenNames.add(key);
          return true;
        });
        for (const project of uniqueProjects) {
          if (filter.value === 'Active' && project.archived || filter.value === 'Archived' && !project.archived) continue;
          const row = element('div', undefined, 'project-row');
          row.dataset.testid = 'project-row';
          const name = element('span', project.name, 'project-name');
          name.tabIndex = 0;
          name.title = 'Rename project';
          name.addEventListener('click', () => renameProject(project));
          row.append(name);
          const summary = element('span', `${project.completedCount}/${project.totalCount} completed`, 'project-summary');
          summary.dataset.testid = 'project-summary';
          row.append(summary);
          const actions = element('div', undefined, 'project-actions');
          const open = element('button', 'Open project');
          open.type = 'button';
          open.addEventListener('click', () => { location.href = `/projects/${project.id}`; });
          actions.append(open);
          const archive = element('button', project.archived ? 'Restore project' : 'Archive project', 'secondary');
          archive.type = 'button';
          archive.addEventListener('click', async () => {
            await api(`/api/projects/${project.id}/${project.archived ? 'restore' : 'archive'}`, { method: 'POST' });
            await refresh();
          });
          actions.append(archive);
          row.append(actions);
          list.append(row);
        }
      }
      async function renameProject(project) {
        const newName = window.prompt('Project name', project.name);
        if (newName === null) return;
        try {
          await api(`/api/projects/${project.id}`, { method: 'PATCH', headers: { 'content-type': 'application/json' }, body: JSON.stringify({ name: newName }) });
          await refresh();
        } catch (error) { alert.textContent = error.message; }
      }
      filter.addEventListener('change', refresh);
      form.addEventListener('submit', async event => {
        event.preventDefault();
        alert.textContent = '';
        const name = input.value.trim();
        if (!name) {
          alert.textContent = 'Project name is required';
          input.focus();
          return;
        }
        try {
          await api('/api/projects', { method: 'POST', headers: { 'content-type': 'application/json' }, body: JSON.stringify({ name }) });
          input.value = '';
          await refresh();
        } catch (error) { alert.textContent = error.message; }
      });
      await refresh();
    }

    async function showProject(id) {
      app.replaceChildren();
      const back = element('button', 'Projects', 'back');
      back.type = 'button';
      back.addEventListener('click', () => { location.href = '/'; });
      app.append(back);
      try {
        const project = await api(`/api/projects/${encodeURIComponent(id)}`);
        app.append(element('h1', project.name));
        if (project.archived) app.append(element('p', 'Archived project'));
        const alert = element('p', '');
        alert.setAttribute('role', 'alert');
        app.append(alert);
        const form = document.createElement('form');
        const label = element('label', 'Task title');
        label.htmlFor = 'task-title';
        const input = document.createElement('input');
        input.id = 'task-title';
        input.type = 'text';
        input.setAttribute('aria-label', 'Task title');
        const submit = element('button', 'Create task');
        submit.type = 'submit';
        submit.disabled = project.archived;
        form.append(label, input, submit);
        app.append(form);
        const filterWrap = element('div', undefined, 'filter');
        const filterLabel = element('label', 'Task filter');
        filterLabel.htmlFor = 'task-filter';
        const filter = document.createElement('select');
        filter.id = 'task-filter';
        filter.setAttribute('aria-label', 'Task filter');
        for (const value of ['All', 'Open', 'Completed']) {
          const option = element('option', value);
          option.value = value;
          filter.append(option);
        }
        filterWrap.append(filterLabel, filter);
        app.append(filterWrap);
        const list = element('section');
        list.setAttribute('aria-label', 'Tasks');
        app.append(list);
        async function refresh() {
          const tasks = await api(`/api/projects/${encodeURIComponent(id)}/tasks`);
          list.replaceChildren();
          for (const task of tasks) {
            if (filter.value === 'Open' && task.completed || filter.value === 'Completed' && !task.completed) continue;
            const row = element('div', undefined, 'task-row');
            row.dataset.testid = 'task-row';
            const checkbox = document.createElement('input');
            checkbox.type = 'checkbox';
            checkbox.checked = task.completed;
            checkbox.disabled = project.archived;
            checkbox.setAttribute('aria-label', `Complete ${task.title}`);
            const title = element('span', task.title, `task-title${task.completed ? ' completed' : ''}`);
            checkbox.addEventListener('change', async () => {
              try {
                await api(`/api/projects/${encodeURIComponent(id)}/tasks/${task.id}`, { method: 'PATCH', headers: { 'content-type': 'application/json' }, body: JSON.stringify({ completed: checkbox.checked }) });
                await refresh();
              } catch (error) { alert.textContent = error.message; }
            });
            row.append(checkbox, title);
            list.append(row);
          }
        }
        filter.addEventListener('change', refresh);
        form.addEventListener('submit', async event => {
          event.preventDefault();
          alert.textContent = '';
          const title = input.value.trim();
          if (!title) { alert.textContent = 'Task title is required'; input.focus(); return; }
          try {
            await api(`/api/projects/${encodeURIComponent(id)}/tasks`, { method: 'POST', headers: { 'content-type': 'application/json' }, body: JSON.stringify({ title }) });
            input.value = '';
            await refresh();
          } catch (error) { alert.textContent = error.message; }
        });
        await refresh();
      } catch {
        app.append(element('h1', 'Project not found'));
      }
    }

    const match = location.pathname.match(/^\/projects\/(\d+)\/?$/);
    if (match) showProject(match[1]); else showProjects();
  </script>
</body>
</html>
